import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Check every element in parallel and raise Bad of the lowest-index bad element."""
    from concurrent.futures import Future, ThreadPoolExecutor, as_completed

    if not xs:
        return []

    errors: dict[int, Bad] = {}
    results: list[int] = [0] * len(xs)

    with ThreadPoolExecutor() as executor:
        futures: dict[Future[int], int] = {
            executor.submit(check, x): i for i, x in enumerate(xs)
        }
        for future in as_completed(futures):
            i = futures[future]
            try:
                results[i] = future.result()
            except Bad as err:
                errors[i] = err

    if errors:
        raise errors[min(errors)]

    return results


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_success() -> None:
    assert all_even([0, 2, 4, 6, 8]) == [0, 2, 4, 6, 8]


def test_all_even_single_failure() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 4, 5, 8])
    assert exc_info.value.n == 5


def test_all_even_lowest_index_raised_first_element() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([1, 3, 5])
    assert exc_info.value.n == 1


def test_all_even_lowest_index_raised_multiple_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 7, 4, 3, 6, 9])
    assert exc_info.value.n == 7


def test_all_even_last_element_failure() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 4, 6, 7])
    assert exc_info.value.n == 7


def test_all_even_large_input_lowest_index_priority() -> None:
    data = [2 * i for i in range(100)]
    data[10] = 11
    data[20] = 21
    data[30] = 31
    with pytest.raises(Bad) as exc_info:
        all_even(data)
    assert exc_info.value.n == 11

